INSERT INTO feature VALUES('compiled-runtime','runtime','A compiled runtime','native-emitter','partial','notable',NULL,'Every runs item executes as patched native code with no interpreter in the loop, the hand-written machine retired; #318''s other rungs stay open: the negative core as dialect operations, foreign calls at the host boundary, the defunctionalization lead, the shared value representation and a persistent cache.','runtime-stencils runtime-emitter','crates/runtime-stencils/tests/agreement.rs crates/runtime-emitter/tests/agreement.rs',NULL,'#318');
